import java.util.*;
public class CF375B {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int count = Integer.parseInt(sc.nextLine());
        String str = sc.next().toLowerCase();
        String original = str;
        char[] chArr = str.toCharArray();
        StringBuilder sb = new StringBuilder(original);
        Stack<Character> stack = new Stack<>();
        for (char c : chArr) {
            stack.push(c);
        }
        List<Integer> bracketIndices = new ArrayList<>();
        for (int i = 0; i < chArr.length; i++) {
            if (chArr[i] == '(' || chArr[i] == ')') {
                stack.pop();
                bracketIndices.add(i);
            }
        }
        TreeMap<Integer, Integer> pairs = new TreeMap<>();
        for (int i = 0; i < bracketIndices.size(); i += 2) {
            pairs.put(bracketIndices.get(i), bracketIndices.get(i + 1));
        }
        List<Integer> removeIndices = new ArrayList<>();
        for (Map.Entry<Integer, Integer> entry : pairs.entrySet()) {
            int start = entry.getKey();
            int end = entry.getValue();
            for (int i = start; i <= end; i++) {
                removeIndices.add(i);
            }
        }
        List<Integer> toRemove = new ArrayList<>(removeIndices);
        char[] filtered = new char[chArr.length - toRemove.size()];
        char[] replaced = new char[filtered.length];
        int fi = 0, ri = 0;
        for (int i = 0; i < chArr.length; i++) {
            if (!toRemove.contains(i)) {
                filtered[fi++] = chArr[i];
            }
        }
        boolean flag = true;
        for (int i = 0; i < chArr.length; i++) {
            if (toRemove.contains(i)) {
                if (chArr[i] == '(' || chArr[i] == ')' || chArr[i] == '_') {
                    if (flag) {
                        replaced[ri++] = ' ';
                        flag = false;
                    }
                } else {
                    replaced[ri++] = chArr[i];
                    flag = true;
                }
            }
        }
        StringBuilder sbResult = new StringBuilder();
        for (char c : replaced) {
            sbResult.append(c);
        }
        String[] parts = sbResult.toString().split(" ");
        List<Integer> afterLengths = new ArrayList<>();
        for (String p : parts) {
            String trimmed = p.trim();
            if (trimmed.length() != 0) {
                afterLengths.add(trimmed.length());
            }
        }
        String replacedStr = str.replaceAll("\\(.*?\\) ?", " ").replace("_", " ");
        String[] originalParts = replacedStr.split(" ");
        List<Integer> beforeLengths = new ArrayList<>();
        for (String p : originalParts) {
            String trimmed = p.trim();
            if (trimmed.length() != 0) {
                beforeLengths.add(trimmed.length());
            }
        }
        Collections.sort(afterLengths);
        int maxLen = afterLengths.size() == 0 ? 0 : afterLengths.get(afterLengths.size() - 1);
        System.out.print(maxLen + " " + beforeLengths.size());
    }
}
